/* ==========================================================================
   Carryo Obsidian — Shopify Online Store 2.0 Theme Stylesheet
   ========================================================================== */

*, *::before, *::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  background-color: var(--carryo-bg);
  color: var(--carryo-ivory);
  color-scheme: dark;
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

body.carryo-body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--carryo-bg);
  color: var(--carryo-ivory);
  line-height: 1.5;
}

main.carryo-main {
  flex: 1 0 auto;
}

h1, h2, h3, h4 {
  font-family: var(--font-display);
  letter-spacing: -0.015em;
  margin: 0;
}

p {
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

button, input, select, textarea {
  font-family: inherit;
  color: inherit;
}

button:focus-visible, a:focus-visible, input:focus-visible, select:focus-visible, textarea:focus-visible {
  outline: 2px solid var(--carryo-gold);
  outline-offset: 2px;
}

.sr-only,
.skip-link:not(:focus) {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link:focus {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 999;
  background: var(--carryo-gold);
  color: #080809;
  padding: 10px 16px;
  border-radius: 8px;
  font-weight: 600;
}

.container {
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

.container--narrow {
  max-width: 48rem;
}

@media (min-width: 640px) {
  .container {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .container {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

.mono {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.text-gold { color: var(--carryo-gold); }
.text-ivory { color: var(--carryo-ivory); }
.text-muted { color: var(--carryo-muted); }
.text-dim { color: var(--carryo-dim); }
.text-xs { font-size: 0.75rem; }
.text-strong { font-weight: 600; color: var(--carryo-ivory); }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  border-radius: 0.5rem;
  font-size: 0.875rem;
  font-weight: 600;
  border: 1px solid transparent;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-gold {
  background-color: var(--carryo-gold);
  color: #080809;
}

.btn-gold:hover:not(:disabled) {
  background-color: var(--carryo-gold-hover);
}

.btn-gold.is-added {
  background-color: #1D3B2B;
  color: #34D399;
}

.btn-surface {
  background-color: #18181D;
  color: var(--carryo-ivory);
  border-color: #2A2A32;
}

.btn-surface:hover:not(:disabled) {
  background-color: #23232A;
}

.btn-sm {
  padding: 0.55rem 1rem;
  font-size: 0.75rem;
}

.btn-lg {
  padding: 0.85rem 1.5rem;
  font-size: 0.875rem;
}

.btn-full {
  width: 100%;
}

.btn-link {
  display: inline-flex;
  align-items: center;
  padding: 0.85rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--carryo-ivory);
  transition: color 150ms ease;
}

.btn-link:hover {
  color: var(--carryo-gold);
}

.icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--carryo-muted);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.icon-btn:hover {
  color: var(--carryo-ivory);
  background: #1C1C22;
}

